import importlib.metadata,sys,pathlib
def discover(root):
    out={}
    for dist in importlib.metadata.distributions(path=[str(root)]):
        for entry in dist.entry_points:
            if entry.group!='opsforge.plugins':continue
            if entry.name in out:raise ValueError('duplicate plugin')
            out[entry.name]=entry
    return out
def load_approved(root,names):
    entries=discover(root)
    before=list(sys.path);sys.path.insert(0,str(pathlib.Path(root).resolve()))
    try:
        loaded={}
        for name in names:
            if name not in entries:raise ValueError('unknown plugin')
            loaded[name]=entries[name].load()
        return loaded
    finally:sys.path[:]=before

